Script.source:
// Doubles what the device reports at /dev/in and sends it back to /dev/out;
// a report rising past a half fires Bell, once until it falls below again.
let above = false;
godot.hear('/dev/in', (x) => {
    godot.send('/dev/out', x * 2);
    if (! above && x > 0.5) {
        above = true;
        godot.fire('B3NK0001');
    } else if (above && x < 0.5) {
        above = false;
    }
});
